CommitDate: Tue Dec 2 12:17:16 2025 +0200

    Bug 1945489 - Replace nsMsgStatusFeedback in SearchDialog. r=mkmelin


    Simply set the text and progress indicator in the status bar of the
    'Search Messages' dialog directly, instead of using the `nsMsgStatusFeedback`
    implementation via `nsIMsgWindow`. Removing the latter as well isn't possible
    without changes to `nsMsgSearchSession::InterruptSearch()`, however.

    Also disable the 'Clear' button while a search is running, since clicking it
    at this point would put the search dialog in a non-functional state.

    Differential Revision: https://phabricator.services.mozilla.com/D274275

diff --git a/mail/base/content/SearchDialog.js b/mail/base/content/SearchDialog.js
index 11ced6e2700..165e3b188c3 100644
--- a/mail/base/content/SearchDialog.js
+++ b/mail/base/content/SearchDialog.js
@@ -9,8 +9,6 @@
 /* globals validateFileName */ // From utilityOverlay.js
 /* globals messageFlavorDataProvider */ // From messenger.js

-/* globals nsMsgStatusFeedback */ // From mailWindow.js
-
 "use strict";

 ChromeUtils.importESModule("chrome://messenger/content/treecol-image.mjs", {
@@ -38,10 +36,12 @@ var gCurrentFolder;
 var gFolderDisplay;

 var gFolderPicker;
-var gStatusFeedback;
+var gStatusText;
+
 var gSearchBundle;

 var gSearchStopButton;
+var gClearButton;

 // Should we try to search online?
 var gSearchOnline = false;
@@ -992,6 +992,12 @@ SearchFolderDisplayWidget.prototype = {
   _showThreadPane() {},

   onSearching(aIsSearching) {
+    const progressBar = document.getElementById("statusbar-icon");
+    const progressBarContainer = document.getElementById(
+      "statusbar-progresspanel"
+    );
+    gClearButton.disabled = aIsSearching;
+    progressBarContainer.hidden = !aIsSearching;
     if (aIsSearching) {
       // Search button becomes the "stop" button
       gSearchStopButton.setAttribute(
@@ -1005,10 +1011,11 @@ SearchFolderDisplayWidget.prototype = {

       // update our toolbar equivalent
       UpdateMailSearch("new-search");
-      // spin the meteors
-      gStatusFeedback._startMeteors();
-      // tell the user that we're searching
-      gStatusFeedback.showStatusString(
+      // Set progress indicator to indeterminate state.
+      progressBar.removeAttribute("value");
+      // Tell the user that we're searching.
+      gStatusText.setAttribute(
+        "value",
         gSearchBundle.GetStringFromName("searchingMessage")
       );
     } else {
@@ -1024,9 +1031,9 @@ SearchFolderDisplayWidget.prototype = {

       // update our toolbar equivalent
       UpdateMailSearch("done-search");
-      // stop spinning the meteors
-      gStatusFeedback._stopMeteors();
-      // set the result test
+      // Reset progress indicator.
+      progressBar.value = 0;
+      // Show the result of the search.
       this.updateStatusResultText();
     }
   },
@@ -1057,7 +1064,7 @@ SearchFolderDisplayWidget.prototype = {
       statusMsg = statusMsg.replace("#1", rowCount);
     }

-    gStatusFeedback.showStatusString(statusMsg);
+    gStatusText.setAttribute("value", statusMsg);
   },
 };

@@ -1125,6 +1132,7 @@ function searchOnUnload() {
 function initializeSearchWindowWidgets() {
   gFolderPicker = document.getElementById("searchableFolders");
   gSearchStopButton = document.getElementById("search-button");
+  gClearButton = document.getElementById("clear-button");
   hideMatchAllItem();

   msgWindow = Cc["@mozilla.org/messenger/msgwindow;1"].createInstance(
@@ -1132,8 +1140,7 @@ function initializeSearchWindowWidgets() {
   );
   msgWindow.domWindow = window;

-  gStatusFeedback = new nsMsgStatusFeedback();
-  msgWindow.statusFeedback = gStatusFeedback;
+  gStatusText = document.getElementById("statusText");

   // functionality to enable/disable buttons using nsSearchResultsController
   // depending of whether items are selected in the search results thread pane.
@@ -1151,7 +1158,7 @@ function onResetSearch(event) {
   onReset(event);
   gFolderDisplay.view.search.clear();

-  gStatusFeedback.showStatusString("");
+  gStatusText.setAttribute("value", "");
 }

 function updateSearchFolderPicker(folder) {
diff --git a/mail/base/content/SearchDialog.xhtml b/mail/base/content/SearchDialog.xhtml
index 65a3ecd65b7..d3fdcac1c4d 100644
--- a/mail/base/content/SearchDialog.xhtml
+++ b/mail/base/content/SearchDialog.xhtml
@@ -106,7 +106,10 @@
                     checked="true"
                     persist="checked"/>
           <spacer style="flex: 10 10;"/>
-          <button label="&resetButton.label;" oncommand="onResetSearch(event);" accesskey="&resetButton.accesskey;"/>
+          <button id="clear-button"
+                  label="&resetButton.label;"
+                  oncommand="onResetSearch(event);"
+                  accesskey="&resetButton.accesskey;"/>
         </hbox>
         <hbox align="center">
           <checkbox id="checkSearchOnline"
@@ -342,8 +345,8 @@

   <hbox id="status-bar" class="statusbar chromeclass-status" role="status">
     <label id="statusText" class="statusbarpanel" crop="end" flex="1"/>
-    <hbox id="statusbar-progresspanel" class="statusbarpanel statusbarpanel-progress" collapsed="collapsed">
-      <html:progress class="progressmeter-statusbar" id="statusbar-icon" value="0" max="100"/>
+    <hbox id="statusbar-progresspanel" class="statusbarpanel statusbarpanel-progress" hidden="hidden">
+      <html:progress class="progressmeter-statusbar" id="statusbar-icon"/>
     </hbox>
   </hbox>
 </html:body>
